// Native-only process CPU benchmark. UI/Swift/JSON service work is not included.
#define TS_PHASE62_INITIAL_NO_MAIN
#include "Phase62InitialLoopNative.cpp"
#undef TS_PHASE62_INITIAL_NO_MAIN
#include <sys/resource.h>
#include <libproc.h>
#include <mach/task_info.h>
namespace {
struct CpuSample {double cpu=0,wall=0;std::uint64_t interrupts=0,packages=0;};
CpuSample cpuSample(){rusage usage{};require(getrusage(RUSAGE_SELF,&usage)==0,"rusage");rusage_info_v4 info{};require(proc_pid_rusage(getpid(),RUSAGE_INFO_V4,reinterpret_cast<rusage_info_t*>(&info))==0,"proc rusage");return {usage.ru_utime.tv_sec+usage.ru_utime.tv_usec*1e-6+usage.ru_stime.tv_sec+usage.ru_stime.tv_usec*1e-6,double(initialNs())*1e-9,info.ri_interrupt_wkups,info.ri_pkg_idle_wkups};}
std::string threads(){thread_act_array_t list=nullptr;mach_msg_type_number_t count=0;require(task_threads(mach_task_self(),&list,&count)==KERN_SUCCESS,"task threads");std::ostringstream out;out<<'[';
 for(unsigned i=0;i<count;++i){thread_extended_info_data_t info{};mach_msg_type_number_t size=THREAD_EXTENDED_INFO_COUNT;auto status=thread_info(list[i],THREAD_EXTENDED_INFO,reinterpret_cast<thread_info_t>(&info),&size);if(i)out<<',';out<<"{\"status\":"<<status<<",\"port\":"<<list[i];if(status==KERN_SUCCESS)out<<",\"name\":"<<ts::prototype::phase58::jsonString(info.pth_name)<<",\"user_ns\":"<<info.pth_user_time<<",\"system_ns\":"<<info.pth_system_time;out<<'}';mach_port_deallocate(mach_task_self(),list[i]);}
 vm_deallocate(mach_task_self(),reinterpret_cast<vm_address_t>(list),count*sizeof(thread_t));out<<']';return out.str();}
void cost(std::ostream& out,const ControlCostValue& value){out<<"{\"calls\":"<<value.calls<<",\"items\":"<<value.items<<",\"object_bytes\":"<<value.objectBytes<<",\"cpu_s\":"<<value.cpuS<<",\"wall_s\":"<<value.wallS<<'}';}
void diagnostics(std::ostream& out,const ProgressiveDiagnostics& d){out<<"{\"session\":"<<d.session<<",\"epoch\":"<<d.renderEpoch<<",\"input_generation\":"<<d.inputGeneration<<",\"missing\":"<<d.missingFrames<<",\"rejected\":"<<d.rejectedWrites<<",\"deadlines\":"<<d.workerDeadlineMisses<<",\"worker_new\":"<<d.workerNewCalls<<",\"workgroup_errors\":"<<d.workgroupErrors<<",\"callback_new\":"<<d.callbackCppNew.value_or(UINT64_MAX)<<",\"rss\":"<<d.rssBytes<<",\"costs_measured\":"<<d.controlCostsMeasured<<",\"analysis_wakes\":"<<d.pipeline.analysisIdleWakes<<",\"seek_wakes\":"<<d.seekDispatchWakes<<",\"checkpoint_peak\":"<<d.pipeline.loopReuse.checkpointPeak<<",\"monitor\":";cost(out,d.monitorCost);out<<",\"sync\":";cost(out,d.syncLoopSpeedCost);out<<",\"input_validation\":";cost(out,d.pipeline.inputValidationCost);out<<",\"speed_copy\":";cost(out,d.pipeline.speedHistoryCopyCost);out<<'}';}
int cpuMain(int argc,char** argv){require(argc==6,"INPUT costs-on|off short|full NEW_OUTPUT sourceSHA");const std::filesystem::path folder=argv[4];require(std::filesystem::create_directories(folder),"fresh output");const bool measured=std::string(argv[2])=="costs-on",full=std::string(argv[3])=="full";const double seconds=full?30:5;std::vector<std::string> ids=full?std::vector<std::string>{"unprepared","off1","off2","off3","loop2s","loop30s","paused","stopped"}:std::vector<std::string>{"off1","paused"};
 {std::ofstream f(folder/"EXPECTED.json");f<<"{\"expected\":"<<ids.size()<<",\"source\":\""<<argv[5]<<"\",\"costs\":"<<measured<<",\"window_s\":"<<seconds<<",\"observer_hz\":5,\"UI_included\":false,\"required_ids\":[";for(std::size_t i=0;i<ids.size();++i)f<<(i?",":"")<<'"'<<ids[i]<<'"';f<<"]}\n";}
 ProgressiveMacPlaybackEngine engine;std::ofstream rows(folder/"measurements.jsonl");std::size_t completed=0;
 const auto sample=[&](const std::string& id,double duration){auto before=engine.getPlaybackDiagnostics();const auto beforeThreads=threads();const auto a=cpuSample();std::uint64_t polls=0;const auto end=std::chrono::steady_clock::now()+std::chrono::duration<double>(duration);while(std::chrono::steady_clock::now()<end){auto state=engine.getStateSnapshot();require(state.state!=State::Failed,state.error.c_str());(void)engine.getCurrentPlaybackPosition();(void)engine.getPlaybackDiagnostics();(void)engine.getLoopSnapshot();++polls;std::this_thread::sleep_for(std::chrono::milliseconds(200));}const auto b=cpuSample();const auto after=engine.getPlaybackDiagnostics();const auto native=engine.getNativeDiagnostics();rows<<std::setprecision(15)<<"{\"id\":\""<<id<<"\",\"cpu_s\":"<<b.cpu-a.cpu<<",\"wall_s\":"<<b.wall-a.wall<<",\"cpu_percent\":"<<100*(b.cpu-a.cpu)/(b.wall-a.wall)<<",\"interrupt_wakeups\":"<<b.interrupts-a.interrupts<<",\"package_wakeups\":"<<b.packages-a.packages<<",\"polls\":"<<polls<<",\"device_rate\":"<<native.deviceRate<<",\"device_buffer\":"<<native.deviceBufferFrames<<",\"before\":";diagnostics(rows,before);rows<<",\"after\":";diagnostics(rows,after);rows<<",\"threads_before\":"<<beforeThreads<<",\"threads_after\":"<<threads()<<"}\n";rows.flush();require(bool(rows),"measurement write");require(after.missingFrames==before.missingFrames&&after.rejectedWrites==before.rejectedWrites,"supply change");++completed;};
 if(full)sample("unprepared",10);ProgressiveOptions options;options.allowExperimentalLoops=true;options.preset=Preset::Candidate;options.initialSpeed=1;options.measureControlCosts=measured;options.callbackRecordLimit=0;phase61_heap_reset();options.allocationHooks={[]()noexcept{callbackNew=0;callbackCounting=true;phase61_heap_begin();},[]()noexcept{phase61_heap_end();callbackCounting=false;},[]()noexcept{return callbackNew;}};
 require(engine.prepare(argv[1],options),"prepare");initialWait(engine,[&]{return engine.getPlaybackState()==State::Ready;});initialWait(engine,[&]{return engine.getPlaybackDiagnostics().pipeline.analysisDoneS>=0;});require(engine.play(),"play");sample("off1",seconds);if(full){sample("off2",seconds);sample("off3",seconds);const auto rate=engine.getPlaybackDiagnostics().sourceSampleRate;
  for(unsigned length:{2,30}){auto state=engine.getStateSnapshot();const auto r=engine.requestLoopRange(30*rate,(30+length)*rate,{state.inputGeneration,state.session,state.renderEpoch});require(r.accepted,r.reason.c_str());initialWait(engine,[&]{return engine.getLoopSnapshot().initialPositionComplete;});sample(length==2?"loop2s":"loop30s",seconds);state=engine.getStateSnapshot();require(engine.requestClearLoop(r.id,{state.inputGeneration,state.session,state.renderEpoch}).accepted,"clear");initialWait(engine,[&]{return !engine.getLoopSnapshot().clearPending;});}
 }
 require(engine.pause(),"pause");sample("paused",seconds);engine.stop();if(full)sample("stopped",seconds);require(!phase61_heap_allocations()&&!phase61_heap_frees(),"callback allocation");const auto owners=ts::prototype::phase58::RealtimePipeline::executionOwnerCounts();require(!owners.alive&&owners.peak<=2,"owner lifetime");std::ofstream f(folder/"SUMMARY.json");f<<"{\"status\":\"PASS\",\"run_complete\":true,\"expected\":"<<ids.size()<<",\"executed\":"<<completed<<",\"owners_peak\":"<<owners.peak<<",\"callback_malloc\":"<<phase61_heap_allocations()<<",\"callback_free\":"<<phase61_heap_frees()<<",\"RT_approval\":\"NOT_ASSESSED\"}\n";return 0;}
}
int main(int argc,char** argv){int code=1;std::thread owner([&]{try{code=cpuMain(argc,argv);}catch(const std::exception& e){std::cerr<<e.what()<<'\n';}});owner.join();return code;}
